from itertools import combinations


def sat_solve(instance):
    """Brute force 3-SAT. Returns True iff satisfiable."""
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for mask in range(1 << m):
        ok = True
        for clause in clauses:
            sat = False
            for lit in clause:
                v = abs(lit)
                val = (mask >> (v - 1)) & 1
                if (lit > 0 and val == 1) or (lit < 0 and val == 0):
                    sat = True
                    break
            if not sat:
                ok = False
                break
        if ok:
            return True
    return False


def ds_min(instance):
    """Exact minimum dominating set size (or None if n==0 -> 0)."""
    n = instance["n"]
    edges = instance["edges"]
    if n == 0:
        return 0
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    closed = [set([i]) | adj[i] for i in range(n)]
    full = set(range(n))
    for size in range(0, n + 1):
        for comb in combinations(range(n), size):
            dom = set()
            for v in comb:
                dom |= closed[v]
            if dom == full:
                return size
    return n


def ds_solve(instance):
    """Brute force Dominating Set with AT MOST k."""
    k = instance["k"]
    if k < 0:
        return False
    n = instance["n"]
    if n == 0:
        return k >= 0
    if k >= n:
        return True
    return ds_min(instance) <= k
EOF
echo done"}

