{"command":"cd /tmp/reduction-hvq_mmel && cat > explore.py <<'EOF'
import itertools, random
from solvers import sat_solve, ds_solve

def all_clauses(m):
    out=[]
    for vs in itertools.combinations(range(1,m+1),3):
        for signs in itertools.product([1,-1],repeat=3):
            out.append([s*v for s,v in zip(signs,vs)])
    return out

def red_A(inst):  # clause vertex isolated, k=m+c
    n=inst["num_vars"]; cl=inst["clauses"]; N=2*n+len(cl); E=[]
    for v in range(1,n+1): E.append([2*(v-1),2*(v-1)+1])
    for j,c in enumerate(cl):
        cv=2*n+j
        for l in c:
            E.append([cv, 2*(abs(l)-1)+(0 if l>0 else 1)])
    return {"n":N,"edges":E,"k":n+len(cl)}

def red_B(inst):  # clause vertex isolated, k=n
    r=red_A(inst); r["k"]=inst["num_vars"]; return r

def red_C(inst):  # clause pair gadget, k=n
    n=inst["num_vars"]; cl=inst["clauses"]; N=2*n+2*len(cl); E=[]
    for v in range(1,n+1): E.append([2*(v-1),2*(v-1)+1])
    def lv(l): return 2*(abs(l)-1)+(0 if l>0 else 1)
    for j,c in enumerate(cl):
        a=2*n+2*j; b=a+1; E.append([a,b])
        for l in c: E.append([a,lv(l)]); E.append([b,lv(l)])
    return {"n":N,"edges":E,"k":n}

def red_D(inst):  # composition: 3SAT -> VC -> DS
    n=inst["num_vars"]; cl=inst["clauses"]
    # VC graph
    N=2*n+3*len(cl); E=[]
    for v in range(1,n+1): E.append([2*(v-1),2*(v-1)+1])
    def lv(l): return 2*(abs(l)-1)+(0 if l>0 else 1)
    for j,c in enumerate(cl):
        a=2*n+3*j; b=a+1; d=a+2
        E.append([a,b]); E.append([b,d]); E.append([a,d])
        E.append([a,lv(c[0])]); E.append([b,lv(c[1])]); E.append([d,lv(c[2])])
    kvc=n+2*len(cl)
    # VC -> DS: add vertex per edge
    E2=[]
    for idx,(u,v) in enumerate(E):
        w=N+idx; E2.append([u,w]); E2.append([v,w])
    return {"n":N+len(E),"edges":E2,"k":kvc}

def test(red, name, maxm=3, full=True):
    cl=all_clauses(maxm)
    bad=0; tot=0
    subsets=[]
    if full:
        for r in range(len(cl)+1):
            subsets.extend(itertools.combinations(cl,r))
    else:
        rng=random.Random(1)
        for _ in range(3000):
            subsets.append(tuple(rng.choice(cl) for _ in range(rng.randint(0,8))))
    for sub in subsets:
        inst={"num_vars":maxm,"clauses":[list(c) for c in sub]}
        tot+=1
        a=sat_solve(inst); b=ds_solve(red(inst))
        if a!=b:
            bad+=1
            if bad<=2: print(f"{name} MISMATCH {inst} sat={a} ds={b}")
    print(f"{name}: {bad} mismatches out of {tot}")

for name,red in [("A",red_A),("B",red_B),("C",red_C),("D",red_D)]:
    test(red,name,3,True)
EOF
