def min_ds(n, edges):
    """Exact minimum dominating set via branch and bound."""
    if n == 0:
        return 0
    closed = [1 << i for i in range(n)]
    for u, v in edges:
        closed[u] |= 1 << v
        closed[v] |= 1 << u
    full = (1 << n) - 1
    best = n

    def rec(dom, selected, count):
        nonlocal best
        if count >= best:
            return
        if dom == full:
            best = count
            return
        und = (~dom) & full
        v = (und & -und).bit_length() - 1
        opts = [i for i in range(n) if (closed[v] >> i) & 1 and not (selected >> i) & 1]
        opts.sort(key=lambda x: -(bin(closed[x] & ~dom).count("1")))
        for x in opts:
            rec(dom | closed[x], selected | (1 << x), count + 1)

    rec(0, 0, 0)
    return best


def ds_solve(instance):
    k = instance["k"]
    if k < 0:
        return False
    n = instance["n"]
    if n == 0:
        return k >= 0
    if k >= n:
        return True
    return min_ds(n, instance["edges"]) <= k
