import itertools, sys
sys.path.insert(0,'.')
from reduce import reduce

def sat_solve(inst):
    m = inst["num_vars"]; clauses = inst["clauses"]
    for bits in itertools.product([False,True], repeat=m):
        ok=True
        for cl in clauses:
            if not any((bits[abs(l)-1] if l>0 else not bits[abs(l)-1]) for l in cl):
                ok=False; break
        if ok: return True
    return False

def ds_solve(inst):
    n=inst["n"]; edges=inst["edges"]; k=inst["k"]
    if k<0: return False
    if k>=n: return True
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    verts=list(range(n))
    for size in range(0,k+1):
        for comb in itertools.combinations(verts,size):
            D=set(comb)
            dom=set(D)
            for u in D: dom|=adj[u]
            if len(dom)==n: return True
    return False

# all clauses on vars 1..3
allcl=[]
for lits in itertools.product([1,-1,2,-2,3,-3],repeat=3):
    if len({abs(x) for x in lits})==3:
        allcl.append(list(lits))
# unique up to order
uniq=[]
seen=set()
for cl in allcl:
    key=frozenset(cl)
    if key not in seen:
        seen.add(key); uniq.append(cl)
print("num clauses m=3:", len(uniq))
mismatch=0
for r in range(0,len(uniq)+1):
    for sub in itertools.combinations(uniq,r):
        inst={"num_vars":3,"clauses":[list(c) for c in sub]}
        s=sat_solve(inst)
        red=reduce(inst)
        d=ds_solve(red)
        if s!=d:
            mismatch+=1
            if mismatch<=10:
                print("MISMATCH sat=",s,"ds=",d, inst, red)
print("total mismatches m=3:", mismatch)
EOF
